type MapControlCatalog = { version: string; contentFingerprint: string; surfaces: string[]; controls: MapControl[] };
type ModSetting = { id: string; modName: string; settingType: string; valueType: string; default?: unknown; minimum?: number; maximum?: number; allowedValues?: string[]; required: boolean };
