type ModSettingsDoc = { artifact: { schemaVersion: number; generatedAtUtc: string; compatibility: { factorioVersion: string; expansion: string; saveName?: string; catalogFingerprint: string }; values: Record<string, ModSettingValue> }; definitions: ModSetting[]; diagnostics: string[] };
type MapGeneration = { seed?: number; width: number; height: number; water: string; startingArea: string; terrainSegmentation: string; peacefulMode: boolean; ironOre: ResourceSettings; copperOre: ResourceSettings; stone: ResourceSettings; coal: ResourceSettings; uraniumOre: ResourceSettings; crudeOil: ResourceSettings; trees: ResourceSettings; enemyBase: ResourceSettings; controlOverrides?: Record<string, { frequency?: string; size?: string; richness?: string }>; evolutionTime: number; evolutionPollution: number; evolutionDestroy: number; enemyExpansionEnabled: boolean; enemyExpansionMinDistance: number; enemyExpansionMaxDistance: number; settlerGroupMinSize: number; settlerGroupMaxSize: number; expansionMinCooldown: number; expansionMaxCooldown: number; cliffElevationInterval: number; cliffElevationOffset: number; cliffRichness: string };
