type Settings = { serverName: string; description: string; serverPassword?: string; maxPlayers: number; visibilityPublic: boolean; visibilityLan?: boolean; autosaveMinutes: number; autosaveSlots?: number; ignorePlayerLimitForReturningPlayers?: boolean; allowCommands?: "true" | "false" | "admins-only"; tags?: string[]; activeSave?: string; channel: "stable" | "experimental"; activeVersion?: string; backupIntervalHours: number; backupRetention: number; timeZone: string; scheduledRestartEnabled?: boolean; scheduledRestartTime?: string; scheduledUpdateChecksEnabled?: boolean; alertsEnabled?: boolean; expansion?: GameProfile; mapGeneration: MapGeneration; mapGenerationProfiles?: Partial<Record<GameProfile, MapGeneration>> };
type UpdateStatus = { availableVersion?: string; checkedVersion?: string; checkedAt: string; error?: string };
