type MaintenanceStatus = { checkedAt: string; backupIntervalHours: number; backupRetention: number; scheduledRestartEnabled: boolean; scheduledRestartTime: string; lastScheduledBackup?: string; nextScheduledBackup?: string; lastUpdateCheck?: string; nextUpdateCheck?: string; recentHistory?: MaintenanceHistoryEntry[] };
type NotificationStatus = { enabled: boolean; discordConfigured: boolean; telegramConfigured: boolean };
type ServerEventHistoryEntry = { eventKind: string; status: "success" | "failure"; timestamp: string; message: string };
type Mod = { name: string; version: string; enabled: boolean; dependencies?: string[]; source?: "portal" | "local"; archiveFileName?: string; sha256?: string; factorioVersionRequirement?: string };
type ModUpdateInfo = { name: string; installedVersion: string; latestVersion?: string; updateAvailable: boolean; missingDependencies: string[]; downloadUrl?: string };
type ModProfile = { name: string; mods: Array<{ name: string; version: string; enabled: boolean }>; createdAt: string; updatedAt: string };
type PortalMod = { [key: string]: unknown; name: string; title?: string; summary?: string; latest_release?: { [key: string]: unknown; version?: string } };
type PortalSearchResponse = { results: PortalMod[]; pagination?: Record<string, unknown> };
type PortalSort = "name" | "version" | "updated" | "downloads";
type ModRecovery = { pending: boolean; message?: string; quarantinedFiles: string[]; startedAt?: string };
type ModPreflight = { operation: string; allowed: boolean; requiresBackup: boolean; activeSave?: string; activeVersion?: string; plannedMods: Mod[]; blockers: string[]; warnings: string[]; downloads: string[] };
type Tab = "overview" | "settings" | "automation" | "versions" | "mods" | "saves" | "players" | "logs" | "health" | "users" | "audit";
type Me = { csrfToken: string; uid?: string; name?: string; role?: "owner" | "admin" | "viewer" };
